package ca

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/ca/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/pgxerr"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; what it writes for a private key
// is whatever Sealer produced, never the key.
type PostgresStore struct {
	q *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{q: db.New(pool)}
}

// Create persists a new Authority.
func (s *PostgresStore) Create(ctx context.Context, a *Authority) error {
	err := s.q.CreateCertificateAuthority(ctx, db.CreateCertificateAuthorityParams{
		OrgGrn:      a.orgGRN.String(),
		Certificate: a.certificate,
		SealedKey:   a.sealedKey,
		NotAfter:    stamp(a.notAfter),
		CreatedAt:   stamp(a.createdAt),
	})
	return pgxerr.Classify(err, "create", nil, ErrAuthorityAlreadyExists)
}

// Get returns the organization's Authority, or ErrAuthorityNotFound.
func (s *PostgresStore) Get(ctx context.Context, orgGRN grn.GRN) (*Authority, error) {
	row, err := s.q.GetCertificateAuthority(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get", ErrAuthorityNotFound, nil)
	}
	return rowToAuthority(row)
}

// rowToAuthority converts a sqlc row into the domain aggregate. A
// stored value that no longer parses is data corruption, hence
// internal.
func rowToAuthority(row db.CertificateAuthority) (*Authority, error) {
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "org grn", errorx.KindInternal)
	}
	return &Authority{
		orgGRN:      orgGRN,
		certificate: row.Certificate,
		sealedKey:   row.SealedKey,
		notAfter:    row.NotAfter.Time,
		createdAt:   row.CreatedAt.Time,
	}, nil
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}
